{
  "sentences": [
    {
      "text": "The step 'Add 18% tax' multiplied the order amount by 18 instead of 1.18 to add an 18% tax.",
      "nodes": [
        "add_tax"
      ]
    },
    {
      "text": "This caused the resulting total to be 4,499.82, which triggered the assertion in 'Check the total is sane' because it exceeded 1,000.",
      "nodes": [
        "add_tax",
        "check"
      ]
    },
    {
      "text": "To fix this, change the operand in the tax calculation step to 1.18.",
      "nodes": [
        "add_tax"
      ]
    }
  ],
  "fix": "Change the operand of 'Add 18% tax' to 1.18"
}

{
  "name": "Order total check",
  "description": "Adds tax to an order and checks the total before logging it.",
  "nodes": [
    {
      "id": "trigger",
      "type": "core.webhook_trigger",
      "config": {}
    },
    {
      "id": "add_tax",
      "type": "transform.number",
      "label": "Add 18% tax",
      "config": {
        "value": "{{trigger.amount}}",
        "operation": "multiply",
        "operand": 1.18,
        "precision": 2
      }
    },
    {
      "id": "check",
      "type": "core.assert",
      "label": "Check the total is sane",
      "config": {
        "left": "{{steps.add_tax.output.value}}",
        "operator": "less_than",
        "right": 1000,
        "message": "The total with tax is over 1,000 — check the tax."
      }
    },
    {
      "id": "log",
      "type": "core.log",
      "label": "Log the total",
      "config": {
        "message": "Order {{trigger.order}}: {{steps.add_tax.output.value}}"
      }
    }
  ],
  "edges": [
    {
      "source": "trigger",
      "target": "add_tax",
